import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD STAGE BACKDROP (gradient surface)
  // ============================================================================
  const stageGroup = new THREE.Group();

  // Gradient backdrop plane (~7x6 units at z=-2.5)
  const stageGeo = new THREE.PlaneGeometry(7, 6);
  const stageUv = uv();
  const gradientColor = mix(
    vec3(0.067, 0.067, 0.063), // #16161d ink (dark base)
    vec3(0.055, 0.055, 0.063)  // #0b0b10 surface (slightly darker)
  ).mul(mix(
    vec3(1),
    vec3(0.98),
    stageUv.y
  ));
  const stageMat = new MeshBasicNodeMaterial();
  stageMat.colorNode = gradientColor;
  const stagePlane = new THREE.Mesh(stageGeo, stageMat);
  stagePlane.position.z = -2.5;
  stageGroup.add(stagePlane);

  // ============================================================================
  // 2. CREATE PRICING CARD 1 LABEL (textured plane + text overlay)
  // ============================================================================
  const cardGroup = new THREE.Group();

  // Load the orb-decor image texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Card plane geometry (aspect-based sizing for the 512x320 atlas region)
  const cardAspect = 512 / 320;
  const cardHeight = 1.2;
  const cardWidth = cardHeight * cardAspect;
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);

  // Build material with texture + subtle grain overlay
  const cardUv = uv();
  const grainIntensity = 0.08;
  const grain = mix(
    vec3(1),
    vec3(Math.random()),
    grainIntensity
  );

  const cardMat = new MeshBasicNodeMaterial();
  let cardMesh = new THREE.Mesh(cardGeo, cardMat);

  // Async texture load → update material
  texturePromise.then((tex) => {
    cardMat.map = tex;
    cardMat.colorNode = mix(
      texture(cardUv.convertTSNToUV()),
      grain,
      0.05
    );
    cardMat.needsUpdate = true;
  }).catch(() => {
    // Fallback: solid surface color if texture fails
    cardMat.colorNode = vec3(0.055, 0.055, 0.063);
  });

  // If no texture loads initially, set fallback
  cardMat.colorNode = vec3(0.055, 0.055, 0.063);

  cardMesh.position.set(0, 0, 0);
  cardGroup.add(cardMesh);

  // ============================================================================
  // 3. ADD TEXT CONTENT ("Pricing 1")
  // ============================================================================
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const pricingLabel = textContent.find(item => item.role === 'headline' || item.text?.includes('Pricing'));

  if (pricingLabel || textContent.length > 0) {
    const displayText = pricingLabel?.text || 'Pricing 1';
    const fontSize = pricingLabel?.typography?.fontSize || 39;

    // Create MSDF text at headline scale (0.34 scene units nominal, scale by fontSize ratio)
    const textMesh = ctx.fontAtlas.createText(displayText, {
      fontSize: fontSize,
      color: '#e8ecf2', // paper color for contrast
      align: 'center',
      maxWidthPx: cardWidth * 200 // Approximate conversion to px
    });

    // Position text above card center, inside the plane
    textMesh.position.set(0, cardHeight * 0.35, 0.05);
    textMesh.scale.multiplyScalar(0.55); // Scale headline to match spec proportion
    cardGroup.add(textMesh);
  }

  // ============================================================================
  // 4. APPLY SCENE POSITION & ROTATION
  // ============================================================================
  const scenePos = config.scenePosition || { x: -3.2, y: 1, z: 0.06 };
  cardGroup.position.set(scenePos.x, scenePos.y, scenePos.z);
  cardGroup.rotation.set(0, 0, 0);
  cardGroup.scale.set(1, 1, 1);

  stageGroup.add(cardGroup);

  // ============================================================================
  // 5. EVENT HANDLERS & CLEANUP
  // ============================================================================
  const timelines = [];

  stageGroup.userData.handlers = {
    onClick: () => {
      // Static node: no click interaction
    },
    onHover: () => {
      // Static node: no hover interaction
    }
  };

  stageGroup.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    cardMat.dispose();
    stageMat.dispose();
    cardGeo.dispose();
    stageGeo.dispose();
  };

  return stageGroup;
}
